  public function executeExpRuleValidate()
  {
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $expediente_regla = ExpedienteReglasPeer::retrieveByPk(trim($this->getRequestParameter('expedientereglas_id')));
    //*******************************************************************************************************
    $expediente_regla_anterior = clone $expediente_regla;
    //*******************************************************************************************************
    $expediente_regla->setEstaActiva(!$expediente_regla->getEstaActiva());
    $expediente_regla->save();
    //*******************************************************************************************************
