        ModulesEnable::Archivo,$expediente_regla->getPrimaryKey(),$usuariologuiado);
    //*******************************************************************************************************
    $this->expediente_regla = $expediente_regla;
  	$this->forward404Unless($expediente_regla);
  }

  public function executeAddExpedienteRegla()
  {
    $subserie_id = trim($this->getRequestParameter('subserie_id'));
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    //*******************************************************************************************************
    try {
      if (!trim($this->getRequestParameter('expedientereglas_id'))){
        $expediente_regla = new ExpedienteReglas();
        $expediente_regla->setFechaCreacion(date("Y-m-d G:i:s"));
        $expediente_regla->setFechaModificacion(date("Y-m-d G:i:s"));
        $message_success = 'El registro fue creado satisfactoriamente';
      }else{
        $expediente_regla = ExpedienteReglasPeer::retrieveByPk($this->getRequestParameter('expedientereglas_id'));
        $expediente_regla->setFechaModificacion(date("Y-m-d G:i:s"));
        $expediente_regla_anterior = clone $expediente_regla;
        $this->forward404Unless($expediente_regla);
        $message_success = 'El registro fue actualizado satisfactoriamente';
      }
      //*****************************************************************************************************
      if (!$subserie_id){ return $this->redirect($this->getRequest()->getScriptName().'/subserie/listExpReglaAuto?subserie_id='.$subserie_id); }
      //*****************************************************************************************************
      $expediente_regla->setUsuarioId($usuariologuiado);
      $expediente_regla->setSubserieId($subserie_id);
      $expediente_regla->setModuloId(trim($this->getRequestParameter('modulo_id')) ? trim($this->getRequestParameter('modulo_id')) : null);
      $expediente_regla->setTipoexpedientereglasId(trim($this->getRequestParameter('tipoexpedientereglas_id')) ? trim($this->getRequestParameter('tipoexpedientereglas_id')) : null);
      $expediente_regla->setNombreRegla(trim($this->getRequestParameter('nombre_regla')) ? trim($this->getRequestParameter('nombre_regla')) : null);
      $expediente_regla->setDescripcionRegla(trim($this->getRequestParameter('descripcion_regla')) ? trim($this->getRequestParameter('descripcion_regla')) : null);
      $expediente_regla->setEstaActiva(trim($this->getRequestParameter('esta_activa')) ? trim($this->getRequestParameter('esta_activa')) : 1);
      $expediente_regla->save();
      //*****************************************************************************************************
      AuditLogPeer::guardarAuditoriaLite("ExpedienteReglas",$expediente_regla_anterior,$expediente_regla,
        ModulesEnable::Archivo,$expediente_regla->getPrimaryKey(),$usuariologuiado);
      //*****************************************************************************************************
      $this->getUser()->setFlash('messages_info', $message_success);
    } catch (PropelException $th) {
      $this->getUser()->setFlash('messages_error', 'Ocurrio un error en la base de datos');
      return $this->redirect($this->getRequest()->getScriptName().'/subserie/addNewExpRule?subserie_id='.$subserie_id);
    } catch (\Exception $th) {
      $this->getUser()->setFlash('messages_error', 'Ocurrio un error en la aplicación(Exception)');
      return $this->redirect($this->getRequest()->getScriptName().'/subserie/addNewExpRule?subserie_id='.$subserie_id);
    } catch (\Throwable $th) {
      $this->getUser()->setFlash('messages_error', 'Ocurrio un error en el servidor(Throwable)');
      return $this->redirect($this->getRequest()->getScriptName().'/subserie/addNewExpRule?subserie_id='.$subserie_id);
    }
    //*****************************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/subserie/listExpReglaAuto?subserie_id='.$subserie_id);
  }

  public function executeAddMetadato()
  {
    if (!trim($this->getRequestParameter('metadato_id'))){
      $metadato = new Metadatos();
      $metadato->setFechaCreacion(date("Y-m-d G:i:s"));
    }else{
      $metadato = MetadatosPeer::retrieveByPk($this->getRequestParameter('metadato_id'));
      $metadato->setFechaModificacion(date("Y-m-d G:i:s"));
      $this->forward404Unless($metadato);
    }
    //*****************************************************************************************************
    $subserie_id = trim($this->getRequestParameter('subserie_id'));
    if (!$subserie_id){ return $this->redirect($this->getRequest()->getScriptName().'/subserie/listMetadatos?subserie_id='.$subserie_id); }
    //*****************************************************************************************************
    $metadato->setTipodatoId(trim($this->getRequestParameter('tipodato_id')) ? trim($this->getRequestParameter('tipodato_id')) : null);
    $metadato->setNombre(trim($this->getRequestParameter('nombre')) ? trim($this->getRequestParameter('nombre')) : null);
    $metadato->setSize(trim($this->getRequestParameter('size')) ? trim($this->getRequestParameter('size')) : null);
    $metadato->setDescripcion(trim($this->getRequestParameter('descripcion')) ? trim($this->getRequestParameter('descripcion')) : null);
    $metadato->setOrden(trim($this->getRequestParameter('orden')) ? trim($this->getRequestParameter('orden')) : null);
    $metadato->setEsObligatorio(trim($this->getRequestParameter('es_obligatorio')) ? trim($this->getRequestParameter('es_obligatorio')) : 0);
    $metadato->setObligatorioConsulta(trim($this->getRequestParameter('obligatorio_consulta')) ? trim($this->getRequestParameter('obligatorio_consulta')) : 0);
    $metadato->setEsConsulta(trim($this->getRequestParameter('es_consulta')) ? trim($this->getRequestParameter('es_consulta')) : 0);
    $metadato->setEsActivo(trim($this->getRequestParameter('es_activo')) ? trim($this->getRequestParameter('es_activo')) : 1);
    $metadato->setRegex(trim($this->getRequestParameter('regex')) ? trim($this->getRequestParameter('regex')) : null);
    $metadato->save();
    //*****************************************************************************************************
    MetadatosSubseriePeer::addNewMetadatoSubserie($metadato->getPrimaryKey(),$subserie_id);
    return $this->redirect($this->getRequest()->getScriptName().'/subserie/listMetadatos?subserie_id='.$subserie_id);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('subserie_id')){
      $subserie = new Subserie();
    }else{
      $subserie = SubseriePeer::retrieveByPk($this->getRequestParameter('subserie_id'));
      $subserie_anterior = $subserie->copy();
      $this->forward404Unless($subserie);
    }
    //*****************************************************************************************************
    $subserie->setDescartefinalsubserieId(1);
    $subserie->setSerieId($this->getRequestParameter('serie_id') ? $this->getRequestParameter('serie_id') : null);
    $subserie->setNivelconfidencialidadId($this->getRequestParameter('nivelconfidencialidad_id') ? $this->getRequestParameter('nivelconfidencialidad_id') : null);
    $subserie->setTipofirmadigitalId($this->getRequestParameter('tipofirmadigital_id') ? $this->getRequestParameter('tipofirmadigital_id') : null);
    $subserie->setCodigo(trim($this->getRequestParameter('codigo')));
    //$subserie->setDescripcion(ereg_replace("[^A-Za-z0-9 ]"," - ",$this->getRequestParameter('descripcion')));
    $subserie->setDescripcion(trim($this->getRequestParameter('descripcion')));
    $subserie->setAnosEnGestion($this->getRequestParameter('anos_en_gestion'));
    $subserie->setAnosEnCentral($this->getRequestParameter('anos_en_central'));
    $subserie->setAnosEnHistorico($this->getRequestParameter('anos_en_historico'));
    $subserie->setAnosValoracionDocumental($this->getRequestParameter('anos_valoracion_documental'));
    $subserie->setEsVisible($this->getRequestParameter('es_visible') ? 1 : 0);
    $subserie->setProcedimiento(trim($this->getRequestParameter('procedimiento')) ? trim($this->getRequestParameter('procedimiento')) : null);
    $subserie->setTipodocsviewId($this->getRequestParameter('tipodocsview_id') ? trim($this->getRequestParameter('tipodocsview_id')) : 1);
    $subserie->save();
    //*****************************************************************************************************
    SubseriePeer::guardarAuditoria($subserie_anterior,$subserie);
    //*****************************************************************************************************
    //$this->deleteDescarteFinal($subserie->getSubserieId());
    //*****************************************************************************************************
    $descarte_subserie = $this->getRequestParameter('descartefinalsubserie_id');
    DescartePorSubseriePeer::addNewDescarteBySubserie($descarte_subserie,$subserie->getPrimaryKey());
    //*****************************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/subserie/show?subserie_id='.$subserie->getSubserieId().'&serie_id='.$this->getRequestParameter('serie_id'));
  }
  
  public function executeValidate()
  {
  	$subserie = SubseriePeer::retrieveByPK($this->getRequestParameter('subserie_id'));
    $subserie_anterior = $subserie->copy();
    //******************************************************************************************
    $subserie->setEsVisible(empty($subserie->getEsVisible()) ? 1 : 0);
    $subserie->save();
    //******************************************************************************************
    SubseriePeer::guardarAuditoria($subserie_anterior,$subserie);
    //******************************************************************************************
    $this->subserie = $subserie;
  	$this->forward404Unless($subserie);
  }

  public function insertDescarteFinal($descatefinal_id,$subserie_id)
  {
    $descarte_por_subserie = new DescartePorSubserie();
    $descarte_por_subserie->setSubserieId($subserie_id);
    $descarte_por_subserie->setDescartefinalsubserieId($descatefinal_id);
    $descarte_por_subserie->save(); 
  }
  
  public function deleteDescarteFinal($subserie_id)
  {
    if(trim($subserie_id))
    {
        $conexion = Propel::getConnection();
    	$consulta = " DELETE FROM %s WHERE %s =".$subserie_id;
    	$sql = sprintf($consulta,DescartePorSubseriePeer::TABLE_NAME,DescartePorSubseriePeer::SUBSERIE_ID);
     	$sentencia = $conexion->prepare($sql);
        $sentencia->execute();
    }
  }
  
  public function deletePermisosPorSubserie($subserie_id)
  {
    if(trim($subserie_id))
    {
        $conexion = Propel::getConnection();
    	$consulta = " DELETE FROM %s WHERE %s =".$subserie_id;
    	$sql = sprintf($consulta,SubseriePorUsuarioPeer::TABLE_NAME,SubseriePorUsuarioPeer::SUBSERIE_ID);
     	$sentencia = $conexion->prepare($sql);
        $sentencia->execute();        
    }
  }
  
  public function executeDelete()
  {
    $c = new Criteria();
    $c->add(UnidadDocumentalPeer::SUBSERIE_ID,$this->getRequestParameter('subserie_id'));
    $qty_expedientes = UnidadDocumentalPeer::doCount($c);
    //************************************************************************************
    $c = new Criteria();
    $c->add(TipoDocumentalPeer::SUBSERIE_ID,$this->getRequestParameter('subserie_id'));
    $qty_tipodocumental = UnidadDocumentalPeer::doCount($c);
    //************************************************************************************
    if($qty_expedientes)
    {
        return $this->redirect($this->getRequest()->getScriptName().'/subserie/show?subserie_id='.$this->getRequestParameter('subserie_id').'&serie_id='.$this->getRequestParameter('serie_id').'&msg_error=1');
    }
    //************************************************************************************
    $this->deleteDescarteFinal($this->getRequestParameter('subserie_id'));
    $this->deletePermisosPorSubserie($this->getRequestParameter('subserie_id'));
    
    $subserie = SubseriePeer::retrieveByPk($this->getRequestParameter('subserie_id'));
    $this->forward404Unless($subserie);
    $subserie->delete();
    //************************************************************************************
  }
}
